const staticData = $getWorkflowStaticData("global");
if (!staticData.processedMeetings) { staticData.processedMeetings = {}; }
if (!staticData.skipLog) { staticData.skipLog = []; }
if (!staticData.metrics) { staticData.metrics = {}; }
staticData.crmWritesAttempted = false;
staticData.crmWriteFailed = false;
staticData.artifactOnce = {};
staticData.analysisCache = staticData.analysisCache || {};
staticData.participantsCompleted = 0;
staticData.expectedExternalParticipants = 0;

function record(reason, meetingId) {
  const row = { meeting_id: meetingId || "", reason: reason, source: "fireflies", recorded_at: $now.toISO() };
  staticData.lastSkip = row;
  staticData.skipLog.push(row);
  if (reason === "duplicate_meeting" || reason === "no_transcript") {
    return [{ json: {
      _ingestion_skip: true,
      meeting_id: meetingId || "",
      skip_reason: reason,
      slack_alert_type: "ingestion_skip",
      slack_text: [
        "ℹ️ *Fireflies Meeting Ingestion Notice*",
        "• *Meeting ID*: `" + String(meetingId || "") + "`",
        "• *Status*: Skipped (`" + reason + "`)"
      ].join("\n")
    } }];
  }
  return [];
}

const wfConfig = $('Workflow Configuration').first().json;
const config = {
  SOURCE: "fireflies",
  AI_MODEL: String(wfConfig.AI_MODEL || "gemini-3.1-flash-lite"),
  UNKNOWN_CONTACT_ACTION: String(wfConfig.UNKNOWN_CONTACT_ACTION || "skip"),
  INTERNAL_EMAIL_DOMAINS: String(wfConfig.INTERNAL_EMAIL_DOMAINS || "yourcompany.com"),
  CREATE_COMPANY_UPDATE: wfConfig.CREATE_COMPANY_UPDATE !== false,
  CREATE_DEAL_UPDATE: wfConfig.CREATE_DEAL_UPDATE !== false,
  CREATE_FOLLOWUP_TASK: wfConfig.CREATE_FOLLOWUP_TASK !== false,
  SEND_SLACK_ALERT: Boolean(wfConfig.SEND_SLACK_ALERT)
};

const payload = items[0].json || {};
let triggerPayload = {};
try { triggerPayload = $("Fireflies Trigger").first().json || {}; } catch (e) { triggerPayload = {}; }

function extractTranscript(src) {
  if (!src || typeof src !== "object") { return null; }
  return (
    (src.body && src.body.data && src.body.data.transcript) ||
    (src.data && src.data.transcript) ||
    (src.body && src.body.transcript) ||
    ((src.id || src.sentences || src.meeting_attendees) ? src : null)
  );
}

const incomingBody = (payload.body && typeof payload.body === "object") ? payload.body : payload;
const triggerBody = (triggerPayload.body && typeof triggerPayload.body === "object") ? triggerPayload.body : triggerPayload;
let transcript = (
  extractTranscript(incomingBody) ||
  extractTranscript(payload) ||
  extractTranscript(triggerBody) ||
  extractTranscript(triggerPayload)
);

if (payload.errors && payload.errors.length && !(transcript && transcript.id)) {
  return record("fireflies_error", payload.data && payload.data.transcript ? payload.data.transcript.id : "");
}

if (!transcript || !String(transcript.id || "").trim()) {
  return record("missing_meeting_id", "");
}

const sentences = Array.isArray(transcript.sentences) ? transcript.sentences : [];
const attendeesRaw = Array.isArray(transcript.meeting_attendees) ? transcript.meeting_attendees : [];
const text = sentences.map((row) => String(row.text || "").trim()).filter(Boolean).join(" ");
if (!text) {
  return record("no_transcript", String(transcript.id));
}
if (!attendeesRaw.length && !sentences.length) {
  return record("invalid_payload", String(transcript.id));
}

if (staticData.processedMeetings[transcript.id]) {
  staticData.metrics.duplicate_meeting = (staticData.metrics.duplicate_meeting || 0) + 1;
  return record("duplicate_meeting", String(transcript.id));
}

staticData.processedMeetings[String(transcript.id)] = {
  processed_at: $now.toISO(),
  source: "fireflies",
  status: "in_progress"
};
staticData.currentMeetingId = String(transcript.id);
staticData.currentSource = "fireflies";
delete staticData.analysisCache[String(transcript.id)];

const attendees = attendeesRaw.map((person) => ({
  name: String(person.displayName || person.name || "").trim(),
  email: String(person.email || person.emailAddress || person.mail || (person.metadata && (person.metadata.email || person.metadata.emailAddress)) || "").trim().toLowerCase(),
  role: ""
}));

const transcriptText = sentences
  .map((row) => String(row.speaker_name || "Speaker").trim() + ": " + String(row.text || "").trim())
  .join("\n");

const meetingId = String(transcript.id || "");
const title = String(transcript.title || "");
const dateIso = transcript.date ? new Date(transcript.date).toISOString() : $now.toISO();
const duration = Number(transcript.duration || 0);
const transcriptUrl = String(transcript.transcript_url || "");
const meetingLink = String(transcript.meeting_link || "");

const meeting = {
  ...config,
  meeting_id: meetingId,
  meetingId: meetingId,
  meeting_title: title,
  title: title,
  meeting_date: dateIso,
  date: dateIso,
  duration_minutes: duration,
  duration: duration,
  transcript_url: transcriptUrl,
  meeting_link: meetingLink,
  meeting_url: transcriptUrl || meetingLink,
  attendees: attendees,
  participants: attendees,
  transcript: transcriptText,
  source: "fireflies"
};

return ["contacts", "companies", "deals"].map((objectType) => ({
  json: { ...meeting, _schemaObject: objectType }
}));

const base = $("Validate & Normalize Meeting").first().json || {};
const meetingBase = Object.assign({}, base);
delete meetingBase._schemaObject;

function asResults(payload) {
  if (!payload) { return []; }
  if (Array.isArray(payload.results)) { return payload.results; }
  if (Array.isArray(payload)) { return payload; }
  return [];
}

const ALLOWED_GROUPS = {
  contacts: { contactinformation: true },
  companies: { companyinformation: true },
  deals: { dealinformation: true }
};

function isWritable(prop) {
  if (!prop || !prop.name) { return false; }
  if (prop.calculated === true) { return false; }
  if (prop.hidden === true) { return false; }
  if (prop.archived === true) { return false; }
  const meta = prop.modificationMetadata || {};
  if (meta.readOnlyValue === true) { return false; }
  if (meta.readOnlyDefinition === true && prop.hubspotDefined === true && String(prop.name).indexOf("hs_") === 0) {
    return false;
  }
  const blocked = {
    hs_object_id: true,
    hs_all_owner_ids: true,
    hs_all_team_ids: true,
    hs_all_accessible_team_ids: true,
    hs_merged_object_ids: true,
    associations: true
  };
  if (blocked[prop.name]) { return false; }
  return true;
}

function simplify(prop) {
  return {
    name: String(prop.name),
    label: String(prop.label || prop.name),
    description: String(prop.description || ""),
    type: String(prop.type || prop.fieldType || "string"),
    groupName: String(prop.groupName || ""),
    hubspotDefined: Boolean(prop.hubspotDefined)
  };
}

function filterObjectProps(results, objectKey) {
  const allowedGroups = ALLOWED_GROUPS[objectKey] || {};
  const writable = results.filter(isWritable).map(simplify);
  const custom = [];
  const groupMatched = [];
  const otherWritable = [];
  for (const prop of writable) {
    if (!prop.hubspotDefined) {
      custom.push(prop);
    } else if (allowedGroups[prop.groupName]) {
      groupMatched.push(prop);
    } else {
      otherWritable.push(prop);
    }
  }
  const MAX = 80;
  const ranked = custom.concat(groupMatched).concat(otherWritable);
  const seen = {};
  const out = [];
  for (const prop of ranked) {
    if (seen[prop.name]) { continue; }
    seen[prop.name] = true;
    out.push({
      name: prop.name,
      label: prop.label,
      description: prop.description,
      type: prop.type
    });
    if (out.length >= MAX) { break; }
  }
  return out;
}

function inferByPropertyNames(results) {
  const names = {};
  for (const prop of results) {
    if (prop && prop.name) {
      names[String(prop.name)] = true;
    }
  }
  if (names.email || names.firstname || names.lastname || names.lifecyclestage) {
    return "contacts";
  }
  if (names.domain || names.industry || names.numberofemployees || names.annualrevenue) {
    return "companies";
  }
  if (names.dealname || names.amount || names.closedate || names.dealstage || names.pipeline) {
    return "deals";
  }
  return "";
}

function resolveObjectKey(item, index) {
  if (item && item.json && item.json._schemaObject) {
    return String(item.json._schemaObject);
  }
  try {
    const p = item && item.pairedItem;
    const sourceIdx = p && typeof p.item === "number" ? p.item : (typeof index === "number" ? index : null);
    if (sourceIdx !== null) {
      const sourceItems = $("Validate & Normalize Meeting").all();
      if (sourceItems[sourceIdx] && sourceItems[sourceIdx].json && sourceItems[sourceIdx].json._schemaObject) {
        return String(sourceItems[sourceIdx].json._schemaObject);
      }
    }
  } catch (e) {}
  const inferred = inferByPropertyNames(asResults(item && item.json));
  if (inferred) { return inferred; }
  return "";
}

const schemas = { contacts: [], companies: [], deals: [] };
for (let i = 0; i < items.length; i++) {
  const key = resolveObjectKey(items[i], i);
  if (!key || !schemas[key]) { continue; }
  schemas[key] = filterObjectProps(asResults(items[i].json), key);
}

const meeting = {
  ...meetingBase,
  hubspot_schemas: schemas,
  hubspot_schema_counts: {
    contacts: schemas.contacts.length,
    companies: schemas.companies.length,
    deals: schemas.deals.length
  }
};

const staticData = $getWorkflowStaticData("global");
if (!staticData.skipLog) { staticData.skipLog = []; }
const domains = String(meeting.INTERNAL_EMAIL_DOMAINS || "").split(",").map((d) => d.trim().toLowerCase()).filter(Boolean);
const seenEmail = {};
const out = [];
const people = Array.isArray(meeting.participants) ? meeting.participants : [];
for (const person of people) {
  const name = String(person.name || "").trim();
  const email = String(person.email || "").trim().toLowerCase();
  if (!email) {
    staticData.skipLog.push({ meeting_id: meeting.meeting_id, reason: "no_email", name: name, recorded_at: $now.toISO() });
    continue;
  }
  if (seenEmail[email]) { continue; }
  seenEmail[email] = true;
  const domain = email.split("@")[1] || "";
  if (domains.indexOf(domain) !== -1) {
    staticData.skipLog.push({ meeting_id: meeting.meeting_id, reason: "internal_domain", email: email, recorded_at: $now.toISO() });
    continue;
  }
  out.push({ json: { ...meeting, participant_name: name, participant_email: email } });
}
staticData.expectedExternalParticipants = out.length;
if (!out.length) {
  staticData.lastSkip = { meeting_id: meeting.meeting_id, reason: "no_external_emails", recorded_at: $now.toISO() };
}
return out;

const meeting = $("Loop Participants").item.json;
const staticData = $getWorkflowStaticData("global");
if (!staticData.skipLog) { staticData.skipLog = []; }
if (!staticData.analysisCache) { staticData.analysisCache = {}; }
staticData.currentMeetingId = meeting.meeting_id;
staticData.currentSource = meeting.source || "fireflies";

function firstAssocId(hit, keys) {
  const a = hit.associations || hit.associationResults || {};
  for (const key of keys) {
    const bucket = a[key];
    if (!bucket) { continue; }
    const results = Array.isArray(bucket) ? bucket : (bucket.results || bucket.data || []);
    if (results[0]) {
      return String(results[0].id || results[0].toObjectId || results[0].to || results[0]);
    }
  }
  if (Array.isArray(hit.associatedDeals) && hit.associatedDeals[0]) {
    return String(hit.associatedDeals[0].id || hit.associatedDeals[0]);
  }
  if (Array.isArray(hit.associatedCompanies) && hit.associatedCompanies[0]) {
    return String(hit.associatedCompanies[0].id || hit.associatedCompanies[0]);
  }
  return "";
}

function resolveCompanyId(hit, props) {
  const fromProperty = sanitizeId(props.associatedcompanyid || "");
  if (fromProperty) { return fromProperty; }
  const fromAssociations = sanitizeId(firstAssocId(hit, ["companies", "company", "Companies", "companyIds"]) || "");
  if (fromAssociations) { return fromAssociations; }
  if (Array.isArray(hit.associatedCompanies) && hit.associatedCompanies[0]) {
    return sanitizeId(hit.associatedCompanies[0].id || hit.associatedCompanies[0].toObjectId || hit.associatedCompanies[0]);
  }
  return "";
}

function resolveDealId(hit, props, assocHit) {
  let dealId = sanitizeId(
    firstAssocId(hit, ["deals", "deal", "Deals", "dealIds"]) ||
    props.associateddealid ||
    props.hs_associated_deal_id ||
    ""
  );
  if (!dealId && Array.isArray(assocHit.results) && assocHit.results[0]) {
    dealId = sanitizeId(assocHit.results[0].toObjectId || assocHit.results[0].id || "");
  }
  return dealId;
}

function splitName(full) {
  const parts = String(full || "").trim().split(/\s+/).filter(Boolean);
  return { first: parts[0] || "", last: parts.length > 1 ? parts.slice(1).join(" ") : "" };
}

function sanitizeId(value) {
  const id = value === null || value === undefined ? "" : String(value).trim();
  if (!id || id === "0" || id === "null" || id === "undefined") { return ""; }
  return id;
}

const searchRaw = $("Search HubSpot Contact").item.json || {};
const hit = (Array.isArray(searchRaw.results) && searchRaw.results[0])
  ? searchRaw.results[0]
  : searchRaw;
const assocHit = $("Lookup Contact Deal Associations").item.json || {};
const props = hit.properties || {};
const contactId = sanitizeId(hit.id || props.hs_object_id || "");
const found = Boolean(contactId);
const policy = String(meeting.UNKNOWN_CONTACT_ACTION || "skip").toLowerCase();
const names = splitName(meeting.participant_name);

let row;
if (!found && (policy === "skip" || policy === "notify")) {
  staticData.skipLog.push({ meeting_id: meeting.meeting_id, reason: "unknown_contact", email: meeting.participant_email, policy: policy, recorded_at: $now.toISO() });
  staticData.lastSkip = { meeting_id: meeting.meeting_id, reason: "unknown_contact", email: meeting.participant_email, policy: policy };
  row = {
    ...meeting,
    contact_found: false,
    skip_crm: true,
    skip_reason: "unknown_contact",
    notify_unknown: policy === "notify",
    contact: { id: "", email: meeting.participant_email, firstname: names.first || meeting.participant_name, lastname: names.last, jobtitle: "", lifecyclestage: "", company: "", owner_id: "" },
    company: { id: "", name: "", industry: "", website: "", owner_id: "" },
    deal: { id: "", name: "", stage: "", amount: "", close_date: "", owner_id: "" }
  };
} else {
  const companyId = resolveCompanyId(hit, props);
  const dealId = resolveDealId(hit, props, assocHit);
  row = {
    ...meeting,
    contact_found: found,
    skip_crm: false,
    skip_reason: "",
    notify_unknown: false,
    create_unknown_contact: !found && policy === "create",
    contact: {
      id: contactId,
      email: props.email || meeting.participant_email,
      firstname: props.firstname || names.first || meeting.participant_name || "",
      lastname: props.lastname || names.last || "",
      jobtitle: props.jobtitle || "",
      lifecyclestage: props.lifecyclestage || "",
      company: props.company || "",
      owner_id: sanitizeId(props.hubspot_owner_id || "")
    },
    company: {
      id: companyId,
      name: String(props.company || ""),
      industry: String(props.industry || ""),
      website: String(props.website || ""),
      owner_id: sanitizeId(props.hubspot_owner_id || "")
    },
    deal: {
      id: dealId,
      name: String(props.dealname || ""),
      stage: String(props.dealstage || ""),
      amount: String(props.amount || ""),
      close_date: String(props.closedate || ""),
      owner_id: sanitizeId(props.hubspot_owner_id || "")
    }
  };
}

if (row.skip_crm) {
  return [{ json: {
    ...row,
    reuse_cached_analysis: false,
    ai_input_text: "Skipped CRM path for " + (row.participant_email || "unknown") + ". Reason: " + (row.skip_reason || "skip_crm")
  } }];
}

const cached = staticData.analysisCache[row.meeting_id];
if (cached) {
  return [{ json: { ...row, reuse_cached_analysis: true, analysis: cached, ai_input_text: "Reuse cached meeting analysis for " + row.meeting_id } }];
}

const schemas = row.hubspot_schemas || { contacts: [], companies: [], deals: [] };
const text = [
  "You are analyzing a sales/customer meeting transcript to produce a CRM update payload.",
  "Map insights ONLY to property names that appear in the HubSpot schemas below. Do not invent property names.",
  "If no suitable property exists for an insight, omit it from the updates objects (use {}).",
  "",
  "Meeting title: " + row.meeting_title,
  "Meeting date: " + row.meeting_date,
  "Contact: " + JSON.stringify(row.contact || {}),
  "Company: " + JSON.stringify(row.company || {}),
  "Deal: " + JSON.stringify(row.deal || {}),
  "",
  "HubSpot Contact properties (writable):",
  JSON.stringify(schemas.contacts || []),
  "",
  "HubSpot Company properties (writable):",
  JSON.stringify(schemas.companies || []),
  "",
  "HubSpot Deal properties (writable):",
  JSON.stringify(schemas.deals || []),
  "",
  "Transcript:",
  row.transcript || ""
].join("\n");

return [{ json: { ...row, reuse_cached_analysis: false, ai_input_text: text } }];

const meetingIn = $("Prepare AI Context").item.json;
const staticData = $getWorkflowStaticData("global");
if (!staticData.analysisCache) { staticData.analysisCache = {}; }
if (!staticData.skipLog) { staticData.skipLog = []; }
if (!staticData.processedMeetings) { staticData.processedMeetings = {}; }
if (!staticData.artifactOnce) { staticData.artifactOnce = {}; }

let meeting = meetingIn;

if (meeting.skip_crm) {
  meeting = { ...meeting, ai_output_valid: false, analysis: { summary_markdown: "" } };
} else if (meeting.reuse_cached_analysis && meeting.analysis && (meeting.analysis.summary_markdown || meeting.analysis.summary)) {
  meeting = { ...meeting, ai_output_valid: true };
} else {
  const raw = items[0].json.output || items[0].json;
  const schemas = meeting.hubspot_schemas || { contacts: [], companies: [], deals: [] };

  function allowedNames(list) {
    const set = {};
    for (const row of (list || [])) {
      if (row && row.name) { set[String(row.name)] = true; }
    }
    return set;
  }

  function sanitizeUpdates(obj, allowed) {
    const out = {};
    if (!obj || typeof obj !== "object" || Array.isArray(obj)) { return out; }
    for (const [key, value] of Object.entries(obj)) {
      if (!allowed[key]) { continue; }
      if (value === null || value === undefined) { continue; }
      const asString = typeof value === "string" ? value.trim() : String(value).trim();
      if (!asString) { continue; }
      out[key] = typeof value === "string" ? asString : value;
    }
    return out;
  }

  const summary = String(raw.summary_markdown || raw.summary || "").trim();
  if (!summary) {
    staticData.lastSkip = { meeting_id: meeting.meeting_id, reason: "invalid_ai_output", recorded_at: $now.toISO() };
    staticData.skipLog.push(staticData.lastSkip);
    return [];
  }

  const intent = String(raw.intent || raw.opportunity_signal || "low").toLowerCase();
  const sentiment = String(raw.sentiment || raw.customer_sentiment || "neutral").toLowerCase();
  const taskRaw = raw.task && typeof raw.task === "object" ? raw.task : {};

  const analysis = {
    summary_markdown: summary,
    summary: summary,
    intent: ["low", "medium", "high"].indexOf(intent) === -1 ? "low" : intent,
    sentiment: ["positive", "neutral", "negative"].indexOf(sentiment) === -1 ? "neutral" : sentiment,
    opportunity_signal: ["low", "medium", "high"].indexOf(intent) === -1 ? "low" : intent,
    customer_sentiment: ["positive", "neutral", "negative"].indexOf(sentiment) === -1 ? "neutral" : sentiment,
    task: {
      create_task: Boolean(taskRaw.create_task),
      title: String(taskRaw.title || "").trim(),
      due_date: String(taskRaw.due_date || "").trim(),
      notes: String(taskRaw.notes || "").trim()
    },
    contact_updates: sanitizeUpdates(raw.contact_updates, allowedNames(schemas.contacts)),
    company_updates: sanitizeUpdates(raw.company_updates, allowedNames(schemas.companies)),
    deal_updates: sanitizeUpdates(raw.deal_updates, allowedNames(schemas.deals))
  };

  staticData.analysisCache[meeting.meeting_id] = analysis;
  meeting = { ...meeting, ai_output_valid: true, analysis: analysis };
}

let decision;

if (meeting.skip_crm) {
  const policy = String(meeting.UNKNOWN_CONTACT_ACTION || "skip").toLowerCase();
  const unknownAlert = policy === "skip" || policy === "notify" || Boolean(meeting.notify_unknown);
  if (!staticData.crmWritesAttempted) {
    staticData.skipOnlyMeeting = true;
  }
  if (unknownAlert) {
    staticData.skipLog.push({
      meeting_id: meeting.meeting_id,
      reason: "unknown_contact_alert",
      email: meeting.participant_email,
      policy: policy,
      recorded_at: $now.toISO()
    });
  }
  const notifyMessage = [
    "⚠️ *HubSpot Sync Skipped — Unknown Contact*",
    "• *Meeting*: `" + String(meeting.meeting_title || "") + "` (`" + String(meeting.meeting_id || "") + "`)",
    "• *Attendee*: `" + String(meeting.participant_name || "") + "` (`" + String(meeting.participant_email || "") + "`)",
    "• *Reason*: Contact does not exist in HubSpot CRM. No notes or tasks were logged."
  ].join("\n");
  decision = {
    update_contact: false,
    update_company: false,
    update_deal: false,
    create_note: false,
    create_task: false,
    send_slack: unknownAlert,
    note_markdown: "",
    task_title: "",
    task_due_date: $now.toFormat("yyyy-MM-dd"),
    task_owner_id: "",
    task_notes: "",
    contact_updates: {},
    company_updates: {},
    deal_updates: {},
    contact_summary: "",
    contact_intent: "",
    notify_message: unknownAlert ? notifyMessage : ""
  };
} else if (!meeting.ai_output_valid) {
  return [];
} else {
  const analysis = meeting.analysis || {};
  const contactUpdates = (analysis.contact_updates && typeof analysis.contact_updates === "object") ? analysis.contact_updates : {};
  const companyUpdates = (analysis.company_updates && typeof analysis.company_updates === "object") ? analysis.company_updates : {};
  const dealUpdates = (analysis.deal_updates && typeof analysis.deal_updates === "object") ? analysis.deal_updates : {};

  const hasContactUpdates = Object.keys(contactUpdates).length > 0;
  const hasCompanyUpdates = Object.keys(companyUpdates).length > 0;
  const hasDealUpdates = Object.keys(dealUpdates).length > 0;

  const firstArtifact = !staticData.artifactOnce[meeting.meeting_id];
  if (firstArtifact) { staticData.artifactOnce[meeting.meeting_id] = true; }

  const noteMarkdown = String(analysis.summary_markdown || analysis.summary || "").trim();
  const createNote = Boolean(noteMarkdown);
  const task = analysis.task || {};
  const createTask = Boolean(
    firstArtifact &&
    meeting.CREATE_FOLLOWUP_TASK &&
    task.create_task &&
    String(task.title || "").trim()
  );

  const taskOwner = (meeting.deal && meeting.deal.id && meeting.deal.owner_id) ? meeting.deal.owner_id : ((meeting.contact && meeting.contact.owner_id) || "");

  const updateContact = Boolean(
    (hasContactUpdates || meeting.create_unknown_contact) &&
    meeting.contact &&
    meeting.contact.email
  );
  const updateCompany = Boolean(
    meeting.CREATE_COMPANY_UPDATE &&
    hasCompanyUpdates &&
    meeting.company &&
    meeting.company.id
  );
  const updateDeal = Boolean(
    meeting.CREATE_DEAL_UPDATE &&
    hasDealUpdates &&
    meeting.deal &&
    meeting.deal.id
  );

  const finalContactUpdates = Object.assign({}, contactUpdates);
  if (meeting.create_unknown_contact) {
    if (meeting.contact.firstname) { finalContactUpdates.firstname = meeting.contact.firstname; }
    if (meeting.contact.lastname) { finalContactUpdates.lastname = meeting.contact.lastname; }
    finalContactUpdates.email = meeting.contact.email;
  }

  staticData.crmWritesAttempted = true;
  staticData.skipOnlyMeeting = false;
  staticData.currentMeetingId = meeting.meeting_id;
  staticData.currentSource = meeting.source || "fireflies";

  const sendHighIntentSlack = Boolean(meeting.SEND_SLACK_ALERT) && analysis.intent === "high" && firstArtifact;
  const contactName = [meeting.contact && meeting.contact.firstname, meeting.contact && meeting.contact.lastname].filter(Boolean).join(" ").trim();
  const highIntentMessage = [
    "🎯 *High-Intent Meeting Alert*",
    "• *Meeting*: `" + String(meeting.meeting_title || "") + "` (`" + String(meeting.meeting_id || "") + "`)",
    "• *Contact*: `" + String(contactName || meeting.participant_name || "") + "` (`" + String((meeting.contact && meeting.contact.email) || meeting.participant_email || "") + "`)",
    "• *Company*: `" + String((meeting.company && meeting.company.name) || "") + "`",
    "• *Intent*: `" + String(analysis.intent || "high") + "`",
    "• *Summary*: " + String(noteMarkdown || analysis.summary || "No summary").slice(0, 500)
  ].join("\n");

  decision = {
    update_contact: updateContact,
    update_company: updateCompany,
    update_deal: updateDeal,
    create_note: createNote,
    create_task: createTask,
    send_slack: sendHighIntentSlack,
    note_markdown: noteMarkdown,
    task_title: String(task.title || "Follow up after meeting"),
    task_due_date: String(task.due_date || $now.plus({ days: 2 }).toFormat("yyyy-MM-dd")),
    task_owner_id: String(taskOwner || ""),
    task_notes: String(task.notes || ""),
    contact_updates: finalContactUpdates,
    company_updates: companyUpdates,
    deal_updates: dealUpdates,
    contact_summary: noteMarkdown,
    contact_intent: analysis.intent || "low",
    notify_message: sendHighIntentSlack ? highIntentMessage : ""
  };
}

const row = { ...meeting, decision };

const ops = [];

function numId(value) {
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? n : null;
}

function isValidAssociationId(value) {
  const id = value === null || value === undefined ? "" : String(value).trim();
  if (!id || id === "0" || id === "null" || id === "undefined") { return null; }
  return id;
}

function toHubSpotTimestamp(ms) {
  const n = Number(ms);
  if (Number.isFinite(n) && n > 0) {
    return Math.trunc(n);
  }
  return Date.now();
}

// NOTE: Standard default HubSpot-defined v3 association type IDs:
// Note associations: 202 (Note -> Contact), 190 (Note -> Company), 214 (Note -> Deal)
// Task associations: 204 (Task -> Contact), 192 (Task -> Company), 216 (Task -> Deal)
function buildAssociations(contactTypeId, companyTypeId, dealTypeId) {
  const out = [];
  const contactId = isValidAssociationId(row.contact && row.contact.id);
  const companyId = isValidAssociationId(row.company && row.company.id);
  const dealId = isValidAssociationId(row.deal && row.deal.id);

  if (contactId) {
    out.push({
      to: { id: contactId },
      types: [{ associationCategory: "HUBSPOT_DEFINED", associationTypeId: contactTypeId }]
    });
  }
  if (companyId) {
    out.push({
      to: { id: companyId },
      types: [{ associationCategory: "HUBSPOT_DEFINED", associationTypeId: companyTypeId }]
    });
  }
  if (dealId) {
    out.push({
      to: { id: dealId },
      types: [{ associationCategory: "HUBSPOT_DEFINED", associationTypeId: dealTypeId }]
    });
  }

  return out;
}

if (decision.update_contact) {
  ops.push({
    name: "contact_upsert",
    method: "POST",
    url: "https://api.hubapi.com/crm/v3/objects/contacts/batch/upsert",
    body: {
      inputs: [{
        idProperty: "email",
        id: row.contact.email,
        properties: decision.contact_updates || {}
      }]
    }
  });
}

if (decision.update_company && isValidAssociationId(row.company && row.company.id)) {
  ops.push({
    name: "company_patch",
    method: "PATCH",
    url: "https://api.hubapi.com/crm/v3/objects/companies/" + String(row.company.id).trim(),
    body: { properties: decision.company_updates || {} }
  });
}

if (decision.update_deal && isValidAssociationId(row.deal && row.deal.id)) {
  ops.push({
    name: "deal_patch",
    method: "PATCH",
    url: "https://api.hubapi.com/crm/v3/objects/deals/" + String(row.deal.id).trim(),
    body: { properties: decision.deal_updates || {} }
  });
}

if (decision.create_note) {
  let startMs = Date.now();
  try {
    const dt = DateTime.fromISO(String(row.meeting_date || ""));
    if (dt.isValid) { startMs = dt.toMillis(); }
  } catch (e) {}

  ops.push({
    name: "create_note",
    method: "POST",
    url: "https://api.hubapi.com/crm/v3/objects/notes",
    body: {
      properties: {
        hs_timestamp: toHubSpotTimestamp(startMs),
        hs_note_body: String(decision.note_markdown || "")
      },
      associations: buildAssociations(202, 190, 214)
    }
  });
}

if (decision.create_task) {
  let dueMs = Date.now();
  try {
    const due = DateTime.fromISO(String(decision.task_due_date || ""));
    if (due.isValid) { dueMs = due.toMillis(); }
  } catch (e) {}

  const taskProps = {
    hs_timestamp: toHubSpotTimestamp(dueMs),
    hs_task_subject: String(decision.task_title || "Follow up after meeting"),
    hs_task_body: String(decision.task_notes || decision.contact_summary || ""),
    hs_task_status: "NOT_STARTED"
  };
  const ownerId = numId(decision.task_owner_id);
  if (ownerId && ownerId > 0) {
    taskProps.hubspot_owner_id = String(ownerId);
  }

  ops.push({
    name: "create_task",
    method: "POST",
    url: "https://api.hubapi.com/crm/v3/objects/tasks",
    body: {
      properties: taskProps,
      associations: buildAssociations(204, 192, 216)
    }
  });
}

staticData._lastSyncContext = {
  meeting_id: row.meeting_id,
  participant_email: row.participant_email,
  decision: decision,
  op_count: ops.length
};

if (!ops.length) {
  return [{ json: {
    ...row,
    decision: decision,
    _no_hubspot_ops: true,
    _trigger_slack: Boolean(decision.send_slack)
  } }];
}

return ops.map((op, idx) => ({
  json: {
    ...row,
    _hubspot_op: op,
    _trigger_slack: Boolean(decision.send_slack && idx === ops.length - 1)
  }
}));

const staticData = $getWorkflowStaticData("global");
const ctx = staticData._lastSyncContext || {};

if (!items.length) {
  const decision = ctx.decision || {};
  return [{ json: {
    meeting_id: ctx.meeting_id || staticData.currentMeetingId || "",
    participant_email: ctx.participant_email || "",
    decision: decision,
    _no_hubspot_ops: true,
    _trigger_slack: Boolean(decision.send_slack)
  } }];
}

return items.map((item) => ({ json: item.json }));

const staticData = $getWorkflowStaticData("global");
staticData.participantsCompleted = Number(staticData.participantsCompleted || 0) + 1;
return items;

const staticData = $getWorkflowStaticData("global");
const completed = Number(staticData.participantsCompleted || 0);
const expected = Number(staticData.expectedExternalParticipants || 0);
if (expected > 0 && completed >= expected) {
  return items;
}
return [];

const staticData = $getWorkflowStaticData("global");
if (!staticData.processedMeetings) { staticData.processedMeetings = {}; }
const meetingId = String(staticData.currentMeetingId || "");

let loopDone = false;
try {
  loopDone = Boolean($('Loop Participants').context.noItemsLeft);
} catch (e) {
  loopDone = true;
}
if (!loopDone) {
  return [];
}

let hardFail = false;
let contactSuccess = false;

function isContactUpsertSuccess(data) {
  if (!data || typeof data !== "object") { return false; }
  if (data.id || data.vid !== undefined) { return true; }
  if (Array.isArray(data.results) && data.results[0] && (data.results[0].id || data.results[0].vid !== undefined)) {
    return true;
  }
  return false;
}

try {
  const syncItems = $("Execute HubSpot Sync").all();
  const opItems = $("Route CRM Output").all().filter((row) => row.json && row.json._hubspot_op && !row.json._no_hubspot_ops);

  for (let i = 0; i < syncItems.length; i++) {
    const data = syncItems[i].json || {};
    const status = Number(data.statusCode || data.status || 0);
    const opName = String((opItems[i] && opItems[i].json && opItems[i].json._hubspot_op && opItems[i].json._hubspot_op.name) || "");

    if (data.status === "error" || data.error || (status >= 400)) {
      hardFail = true;
      staticData.crmWriteFailed = true;
    }

    if (opName === "contact_upsert" && isContactUpsertSuccess(data)) {
      contactSuccess = true;
    }
  }
} catch (e) {
  // Execute HubSpot Sync may not have run (skip-only / empty-op paths).
}

if (meetingId && !hardFail && !staticData.crmWriteFailed) {
  let canComplete = false;
  if (!staticData.crmWritesAttempted || staticData.skipOnlyMeeting) {
    canComplete = true;
  } else if (contactSuccess) {
    canComplete = true;
  }
  if (canComplete) {
    staticData.processedMeetings[meetingId] = {
      processed_at: $now.toISO(),
      source: staticData.currentSource || "fireflies",
      status: "completed"
    };
  }
}

return [];
